changeSet.sql:
CREATE TABLE answer_votes (
    id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    answer_id  UUID NOT NULL REFERENCES answers(id) ON DELETE CASCADE,
    user_id    UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    weight     SMALLINT NOT NULL,
    voted_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT answer_votes_weight_check CHECK (weight IN (-1, 1)),
    CONSTRAINT answer_votes_unique UNIQUE (answer_id, user_id)
);

CREATE INDEX idx_answer_votes_answer ON answer_votes(answer_id);
CREATE INDEX idx_answer_votes_user ON answer_votes(user_id);

rollback.sql:
DROP INDEX IF EXISTS idx_answer_votes_user;
DROP INDEX IF EXISTS idx_answer_votes_answer;
DROP TABLE IF EXISTS answer_votes;
